BFF (Backend for Frontend).ejemplo:
// Agregación paralela en un BFF (TypeScript)
export async function getDashboardSummary(userId: string) {
  const [profile, orders, alerts] = await Promise.allSettled([
    usersClient.getProfile(userId),
    ordersClient.listRecent(userId, { limit: 5 }),
    notificationsClient.unreadCount(userId),
  ]);
  return {
    displayName: profile.status === 'fulfilled' ? profile.value.name : 'Usuario',
    recentOrders: orders.status === 'fulfilled' ? orders.value.items : [],
    unreadAlerts: alerts.status === 'fulfilled' ? alerts.value.count : 0,
  };
}

