// Middleware de autorización basado en permisos granulares
function requirePermission(required: string) {
  return (req: Request, res: Response, next: NextFunction) => {
    const perms = req.auth.permissions; // cargados por tenant + rol
    if (!perms.has(required)) {
      return res.status(403).json({ error: 'forbidden', missing: required });
    }
    return next();
  };
}
